def count_Substrings(s):
    def has_equal_sum_and_length(substring):
        return sum(int(digit) for digit in substring) == len(substring)

    total_count = 0
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substring = s[i:j]
            if has_equal_sum_and_length(substring):
                total_count += 1
    return total_count

