def recursive_list_sum(lst):
    def flatten_and_sum(sublist):
        return sum(flatten(sublist))

    def flatten(lis):
        """Flatten a nested list structure."""
        for el in lis:
            if isinstance(el, list):
                yield from flatten(el)
            else:
                yield el

    return flatten_and_sum(lst)

