def is_Diff(num):
    def diff_sum(num):
        # Calculate the difference between the sum of digits at odd and even positions
        return sum(int(digit) for i, digit in enumerate(str(abs(num))) if i % 2 == 0) - sum(int(digit) for i, digit in enumerate(str(abs(num))) if i % 2 != 0)

    # Check if the calculated difference is divisible by 11
    return diff_sum(num) % 11 == 0

